import { useState, useCallback, useEffect } from "react";
import {
  json,
  type ActionFunctionArgs,
  type HeadersFunction,
  type LoaderFunctionArgs,
} from "react-router";
import { useLoaderData, useActionData, useFetcher } from "react-router";
import {
  Page,
  Layout,
  Card,
  Text,
  InlineStack,
  BlockStack,
  Badge,
  Button,
  Box,
  Divider,
  TextField,
  Select,
  Checkbox,
  EmptyState,
  SkeletonPage,
  SkeletonBodyText,
  Modal,
  FormLayout,
  IndexTable,
  useIndexResourceState,
} from "@shopify/polaris";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import db from "../db.server";

// ─── Types ────────────────────────────────────────────────────────────────────

interface ResultPageData {
  id: string;
  quizId: string;
  title: string;
  description: string | null;
  type: string;
  minScore: number | null;
  maxScore: number | null;
  matchTags: string[];
  productLimit: number;
  layout: string;
  showDiscount: boolean;
  discountType: string | null;
  discountValue: number | null;
  discountCode: string | null;
  ctaText: string | null;
  ctaUrl: string | null;
  styling: Record<string, unknown>;
  position: number;
  createdAt: string;
  updatedAt: string;
}

interface QuizSummary {
  id: string;
  title: string;
  status: string;
}

interface LoaderData {
  quiz: QuizSummary;
  resultPages: ResultPageData[];
}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

const typeOptions = [
  { label: "Default", value: "default" },
  { label: "Score Range", value: "score-range" },
  { label: "Tag Match", value: "tag-match" },
];

const layoutOptions = [
  { label: "Grid", value: "grid" },
  { label: "List", value: "list" },
  { label: "Carousel", value: "carousel" },
];

const discountTypeOptions = [
  { label: "Percentage (%)", value: "percentage" },
  { label: "Fixed amount ($)", value: "fixed" },
];

const productLimitOptions = Array.from({ length: 10 }, (_, i) => ({
  label: String(i + 1),
  value: String(i + 1),
}));

function typeBadgeTone(
  type: string
): "info" | "success" | "attention" | undefined {
  if (type === "score-range") return "info";
  if (type === "tag-match") return "success";
  return undefined;
}

function typeBadgeLabel(type: string): string {
  if (type === "score-range") return "Score Range";
  if (type === "tag-match") return "Tag Match";
  return "Default";
}

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request, params }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id;

  if (!quizId) {
    throw json({ error: "Missing quiz ID" }, { status: 400 });
  }

  try {
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
      include: {
        resultPages: { orderBy: { position: "asc" } },
      },
    });

    if (!quiz) {
      throw json({ error: "Quiz not found" }, { status: 404 });
    }

    const resultPages: ResultPageData[] = quiz.resultPages.map((r) => ({
      id: r.id,
      quizId: r.quizId,
      title: r.title,
      description: r.description,
      type: r.type,
      minScore: r.minScore,
      maxScore: r.maxScore,
      matchTags: parseSafe<string[]>(r.matchTags, []),
      productLimit: r.productLimit,
      layout: r.layout,
      showDiscount: r.showDiscount,
      discountType: r.discountType,
      discountValue: r.discountValue,
      discountCode: r.discountCode,
      ctaText: r.ctaText,
      ctaUrl: r.ctaUrl,
      styling: parseSafe<Record<string, unknown>>(r.styling, {}),
      position: r.position,
      createdAt: r.createdAt.toISOString(),
      updatedAt: r.updatedAt.toISOString(),
    }));

    return json<LoaderData>({
      quiz: {
        id: quiz.id,
        title: quiz.title,
        status: quiz.status,
      },
      resultPages,
    });
  } catch (error) {
    if (error instanceof Response) throw error;
    throw json({ error: "Failed to load result pages" }, { status: 500 });
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request, params }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const quizId = params.id!;
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    // Verify quiz ownership before any mutation
    const quiz = await db.quiz.findFirst({
      where: { id: quizId, shop: session.shop },
    });
    if (!quiz) {
      return json({ error: "Quiz not found" }, { status: 404 });
    }

    switch (intent) {
      case "create": {
        const title = String(formData.get("title") ?? "Result Page").trim() || "Result Page";
        const type = String(formData.get("type") ?? "default");
        const count = await db.resultPage.count({ where: { quizId } });
        await db.resultPage.create({
          data: {
            quizId,
            title,
            type,
            position: count,
          },
        });
        return json({ success: true, message: "Result page created." });
      }

      case "update": {
        const pageId = String(formData.get("pageId") ?? "").trim();
        if (!pageId) {
          return json({ error: "Missing page ID" }, { status: 400 });
        }

        // Verify page belongs to this quiz (which we already confirmed belongs to shop)
        const existingPage = await db.resultPage.findFirst({
          where: { id: pageId, quizId },
        });
        if (!existingPage) {
          return json({ error: "Result page not found" }, { status: 404 });
        }

        const title = String(formData.get("title") ?? "").trim();
        const description = String(formData.get("description") ?? "").trim() || null;
        const type = String(formData.get("type") ?? "default");
        const layout = String(formData.get("layout") ?? "grid");
        const productLimit = parseInt(String(formData.get("productLimit") ?? "4"), 10);
        const showDiscount = formData.get("showDiscount") === "true";
        const ctaText = String(formData.get("ctaText") ?? "").trim() || null;
        const ctaUrl = String(formData.get("ctaUrl") ?? "").trim() || null;

        // Score-range fields
        const minScoreRaw = formData.get("minScore");
        const maxScoreRaw = formData.get("maxScore");
        const minScore =
          minScoreRaw !== null && String(minScoreRaw).trim() !== ""
            ? parseInt(String(minScoreRaw), 10)
            : null;
        const maxScore =
          maxScoreRaw !== null && String(maxScoreRaw).trim() !== ""
            ? parseInt(String(maxScoreRaw), 10)
            : null;

        // Tag-match fields
        const matchTagsRaw = String(formData.get("matchTags") ?? "")
          .split(",")
          .map((t) => t.trim())
          .filter(Boolean);
        const matchTags = JSON.stringify(matchTagsRaw);

        // Discount fields
        const discountType = showDiscount
          ? String(formData.get("discountType") ?? "percentage") || null
          : null;
        const discountValueRaw = formData.get("discountValue");
        const discountValue =
          showDiscount && discountValueRaw !== null && String(discountValueRaw).trim() !== ""
            ? parseFloat(String(discountValueRaw))
            : null;
        const discountCode = showDiscount
          ? String(formData.get("discountCode") ?? "").trim() || null
          : null;

        if (!title) {
          return json({ error: "Title is required" }, { status: 400 });
        }

        await db.resultPage.update({
          where: { id: pageId },
          data: {
            title,
            description,
            type,
            minScore: type === "score-range" ? minScore : null,
            maxScore: type === "score-range" ? maxScore : null,
            matchTags: type === "tag-match" ? matchTags : "[]",
            layout,
            productLimit: isNaN(productLimit) ? 4 : productLimit,
            showDiscount,
            discountType,
            discountValue,
            discountCode,
            ctaText,
            ctaUrl,
            updatedAt: new Date(),
          },
        });

        return json({ success: true, message: "Result page saved." });
      }

      case "delete": {
        const pageId = String(formData.get("pageId") ?? "").trim();
        if (!pageId) {
          return json({ error: "Missing page ID" }, { status: 400 });
        }

        // Verify page belongs to this quiz
        const page = await db.resultPage.findFirst({
          where: { id: pageId, quizId },
        });
        if (!page) {
          return json({ error: "Result page not found" }, { status: 404 });
        }

        await db.resultPage.delete({ where: { id: pageId } });

        // Re-index positions after delete
        const remaining = await db.resultPage.findMany({
          where: { quizId },
          orderBy: { position: "asc" },
        });
        await Promise.all(
          remaining.map((p, idx) =>
            db.resultPage.update({ where: { id: p.id }, data: { position: idx } })
          )
        );

        return json({ success: true, message: "Result page deleted." });
      }

      case "reorder": {
        const orderJson = String(formData.get("order") ?? "[]");
        let order: string[];
        try {
          order = JSON.parse(orderJson) as string[];
        } catch {
          return json({ error: "Invalid order data" }, { status: 400 });
        }
        await Promise.all(
          order.map((pageId, idx) =>
            db.resultPage.updateMany({
              where: { id: pageId, quizId },
              data: { position: idx },
            })
          )
        );
        return json({ success: true, message: "Order updated." });
      }

      default:
        return json({ error: "Unknown action" }, { status: 400 });
    }
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error(`Results action "${intent}" failed:`, error);
    return json({ error: "Action failed. Please try again." }, { status: 500 });
  }
};

// ─── Edit Panel ───────────────────────────────────────────────────────────────

interface EditPanelProps {
  page: ResultPageData;
  onDelete: (pageId: string) => void;
  isSaving: boolean;
}

function EditPanel({ page, onDelete, isSaving }: EditPanelProps) {
  const fetcher = useFetcher<typeof action>();

  const [title, setTitle] = useState(page.title);
  const [description, setDescription] = useState(page.description ?? "");
  const [type, setType] = useState(page.type);
  const [minScore, setMinScore] = useState(
    page.minScore !== null ? String(page.minScore) : ""
  );
  const [maxScore, setMaxScore] = useState(
    page.maxScore !== null ? String(page.maxScore) : ""
  );
  const [matchTags, setMatchTags] = useState(page.matchTags.join(", "));
  const [layout, setLayout] = useState(page.layout);
  const [productLimit, setProductLimit] = useState(String(page.productLimit));
  const [showDiscount, setShowDiscount] = useState(page.showDiscount);
  const [discountType, setDiscountType] = useState(
    page.discountType ?? "percentage"
  );
  const [discountValue, setDiscountValue] = useState(
    page.discountValue !== null ? String(page.discountValue) : ""
  );
  const [discountCode, setDiscountCode] = useState(page.discountCode ?? "");
  const [ctaText, setCtaText] = useState(page.ctaText ?? "");
  const [ctaUrl, setCtaUrl] = useState(page.ctaUrl ?? "");
  const shopify = useAppBridge();

  // Reset local state when page selection changes
  useEffect(() => {
    setTitle(page.title);
    setDescription(page.description ?? "");
    setType(page.type);
    setMinScore(page.minScore !== null ? String(page.minScore) : "");
    setMaxScore(page.maxScore !== null ? String(page.maxScore) : "");
    setMatchTags(page.matchTags.join(", "));
    setLayout(page.layout);
    setProductLimit(String(page.productLimit));
    setShowDiscount(page.showDiscount);
    setDiscountType(page.discountType ?? "percentage");
    setDiscountValue(page.discountValue !== null ? String(page.discountValue) : "");
    setDiscountCode(page.discountCode ?? "");
    setCtaText(page.ctaText ?? "");
    setCtaUrl(page.ctaUrl ?? "");
  }, [page.id]); // eslint-disable-line react-hooks/exhaustive-deps

  // Toast from fetcher (inline save)
  useEffect(() => {
    if (!fetcher.data) return;
    if ("success" in fetcher.data && fetcher.data.success && "message" in fetcher.data) {
      shopify.toast.show(String(fetcher.data.message), { duration: 3000 });
    } else if ("error" in fetcher.data && fetcher.data.error) {
      shopify.toast.show(String(fetcher.data.error), { duration: 4000, isError: true });
    }
  }, [fetcher.data, shopify]);

  const handleSave = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "update");
    fd.set("pageId", page.id);
    fd.set("title", title);
    fd.set("description", description);
    fd.set("type", type);
    fd.set("minScore", minScore);
    fd.set("maxScore", maxScore);
    fd.set("matchTags", matchTags);
    fd.set("layout", layout);
    fd.set("productLimit", productLimit);
    fd.set("showDiscount", String(showDiscount));
    fd.set("discountType", discountType);
    fd.set("discountValue", discountValue);
    fd.set("discountCode", discountCode);
    fd.set("ctaText", ctaText);
    fd.set("ctaUrl", ctaUrl);
    fetcher.submit(fd, { method: "POST" });
  }, [
    fetcher,
    page.id,
    title,
    description,
    type,
    minScore,
    maxScore,
    matchTags,
    layout,
    productLimit,
    showDiscount,
    discountType,
    discountValue,
    discountCode,
    ctaText,
    ctaUrl,
  ]);

  return (
    <Card>
      <BlockStack gap="400">
        <InlineStack align="space-between" blockAlign="center">
          <Text as="h3" variant="headingSm" fontWeight="semibold">
            Edit result page
          </Text>
          <Badge tone={typeBadgeTone(type)}>{typeBadgeLabel(type)}</Badge>
        </InlineStack>

        <Divider />

        <FormLayout>
          <TextField
            label="Title"
            value={title}
            onChange={setTitle}
            autoComplete="off"
            requiredIndicator
          />
          <TextField
            label="Description"
            value={description}
            onChange={setDescription}
            autoComplete="off"
            multiline={3}
          />
          <Select
            label="Result page type"
            options={typeOptions}
            value={type}
            onChange={setType}
          />

          {type === "score-range" && (
            <FormLayout.Group>
              <TextField
                label="Minimum score"
                type="number"
                value={minScore}
                onChange={setMinScore}
                autoComplete="off"
                placeholder="0"
              />
              <TextField
                label="Maximum score"
                type="number"
                value={maxScore}
                onChange={setMaxScore}
                autoComplete="off"
                placeholder="100"
              />
            </FormLayout.Group>
          )}

          {type === "tag-match" && (
            <TextField
              label="Match tags (comma-separated)"
              value={matchTags}
              onChange={setMatchTags}
              autoComplete="off"
              placeholder="skincare, sensitive, dry"
              helpText="Shoppers whose answers match these product tags will see this result page."
            />
          )}

          <Select
            label="Product display layout"
            options={layoutOptions}
            value={layout}
            onChange={setLayout}
          />

          <Select
            label="Product limit"
            options={productLimitOptions}
            value={productLimit}
            onChange={setProductLimit}
          />

          <Checkbox
            label="Show discount"
            checked={showDiscount}
            onChange={setShowDiscount}
            helpText="Display a discount code on this result page."
          />

          {showDiscount && (
            <>
              <FormLayout.Group>
                <Select
                  label="Discount type"
                  options={discountTypeOptions}
                  value={discountType}
                  onChange={setDiscountType}
                />
                <TextField
                  label="Discount value"
                  type="number"
                  value={discountValue}
                  onChange={setDiscountValue}
                  autoComplete="off"
                  placeholder={discountType === "percentage" ? "10" : "5.00"}
                  suffix={discountType === "percentage" ? "%" : "$"}
                />
              </FormLayout.Group>
              <TextField
                label="Discount code"
                value={discountCode}
                onChange={setDiscountCode}
                autoComplete="off"
