export default function ResultPagesEditor() {
  const { quiz, resultPages } = useLoaderData<typeof loader>();
  const actionData = useActionData<typeof action>();
  const fetcher = useFetcher<typeof action>();
  const shopify = useAppBridge();

  const [selectedPageId, setSelectedPageId] = useState<string | null>(
    resultPages.length > 0 ? resultPages[0].id : null
  );
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);
  const [createModalOpen, setCreateModalOpen] = useState(false);
  const [newPageTitle, setNewPageTitle] = useState("");
  const [newPageType, setNewPageType] = useState("default");

  const selectedPage = resultPages.find((p) => p.id === selectedPageId) ?? null;

  // IndexTable resource state (for row selection highlight)
  const { selectedResources, allResourcesSelected, handleSelectionChange } =
    useIndexResourceState(resultPages.map((p) => ({ id: p.id })));

  // Toast from page-level action (create / delete / reorder)
  useEffect(() => {
    if (!actionData) return;
    if ("success" in actionData && actionData.success && "message" in actionData) {
      shopify.toast.show(String(actionData.message), { duration: 3000 });
    } else if ("error" in actionData && actionData.error) {
      shopify.toast.show(String(actionData.error), { duration: 4000, isError: true });
    }
  }, [actionData, shopify]);

  // Auto-select first page after new creation (resultPages re-loads via loader)
  useEffect(() => {
    if (resultPages.length > 0 && !selectedPageId) {
      setSelectedPageId(resultPages[0].id);
    }
  }, [resultPages, selectedPageId]);

  const handleDeleteRequest = useCallback((pageId: string) => {
    setPendingDeleteId(pageId);
    setDeleteModalOpen(true);
  }, []);

  const handleDeleteConfirm = useCallback(() => {
    if (!pendingDeleteId) return;
    const fd = new FormData();
    fd.set("intent", "delete");
    fd.set("pageId", pendingDeleteId);
    fetcher.submit(fd, { method: "POST" });
    // Deselect if we're deleting the selected page
    if (selectedPageId === pendingDeleteId) {
      setSelectedPageId(null);
    }
    setDeleteModalOpen(false);
    setPendingDeleteId(null);
  }, [fetcher, pendingDeleteId, selectedPageId]);

  const handleCreateConfirm = useCallback(() => {
    const fd = new FormData();
    fd.set("intent", "create");
    fd.set("title", newPageTitle.trim() || "Result Page");
    fd.set("type", newPageType);
    fetcher.submit(fd, { method: "POST" });
    setCreateModalOpen(false);
    setNewPageTitle("");
    setNewPageType("default");
  }, [fetcher, newPageTitle, newPageType]);

  const isMutating = fetcher.state !== "idle";

  return (
    <>
      <Page
        title="Result Pages"
        subtitle={quiz.title}
        backAction={{ content: "Quiz editor", url: `/app/quizzes/${quiz.id}` }}
        primaryAction={{
          content: "Add result page",
          onAction: () => setCreateModalOpen(true),
