              Add at least one to display product recommendations.
            </p>
          </EmptyState>
        ) : (
          <Layout>
            {/* Left sidebar — result page list */}
            <Layout.Section variant="oneThird">
              <Card padding="0">
                <Box padding="400">
                  <Text as="h3" variant="headingSm" fontWeight="semibold">
                    Result pages ({resultPages.length})
                  </Text>
                </Box>
                <Divider />
                <IndexTable
                  resourceName={{
                    singular: "result page",
                    plural: "result pages",
                  }}
                  itemCount={resultPages.length}
                  selectedItemsCount={
                    allResourcesSelected ? "All" : selectedResources.length
                  }
                  onSelectionChange={handleSelectionChange}
                  headings={[{ title: "Page" }]}
                  selectable={false}
                >
                  {resultPages.map((page, index) => (
                    <IndexTable.Row
                      id={page.id}
                      key={page.id}
                      position={index}
                      selected={page.id === selectedPageId}
                      onClick={() => setSelectedPageId(page.id)}
                    >
                      <IndexTable.Cell>
                        <BlockStack gap="050">
                          <InlineStack gap="200" blockAlign="center">
                            <Text as="p" variant="bodySm" fontWeight="semibold" truncate>
                              {page.title}
                            </Text>
                            <Badge tone={typeBadgeTone(page.type)}>
                              {typeBadgeLabel(page.type)}
                            </Badge>
