interface WidgetStyling {
  primaryColor: string;
  borderRadius: string;
  fontSize: string;
}

interface WidgetBranding {
  showPoweredBy: boolean;
  logoUrl?: string;
}

interface TriggerValue {
  scrollDepth?: string;
  delaySeconds?: string;
}

interface ConfigData {
  id: string;
  shop: string;
  position: string;
  triggerType: string;
  triggerValue: TriggerValue;
