}

// ─── Helpers ──────────────────────────────────────────────────────────────────

function parseSafe<T>(str: string, fallback: T): T {
  try {
    return JSON.parse(str) as T;
  } catch {
    return fallback;
  }
}

const positionOptions = [
  { label: "Embedded (inline block)", value: "embedded" },
  { label: "Popup (modal overlay)", value: "popup" },
  { label: "Slide-in (side panel)", value: "slide-in" },
  { label: "Full Page", value: "full-page" },
];

const triggerTypeOptions = [
  { label: "Button Click", value: "button" },
  { label: "Scroll Depth", value: "scroll" },
  { label: "Timer / Delay", value: "timer" },
  { label: "Exit Intent", value: "exit-intent" },
];

function positionBadgeTone(
  position: string
): "info" | "success" | "attention" | undefined {
  if (position === "popup") return "attention";
  if (position === "slide-in") return "info";
  if (position === "full-page") return "success";
  return undefined;
}

function positionLabel(value: string): string {
  return positionOptions.find((o) => o.value === value)?.label ?? value;
}

function triggerLabel(value: string): string {
  return triggerTypeOptions.find((o) => o.value === value)?.label ?? value;
}

// ─── Loader ───────────────────────────────────────────────────────────────────

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);

  try {
    let config = await db.widgetConfig.findUnique({
      where: { shop: session.shop },
    });

    if (!config) {
      config = await db.widgetConfig.create({
        data: { shop: session.shop },
      });
    }

    return json<LoaderData>({
      config: {
        id: config.id,
        shop: config.shop,
        position: config.position,
        triggerType: config.triggerType,
        triggerValue: parseSafe<TriggerValue>(config.triggerValue, {}),
        styling: parseSafe<WidgetStyling>(config.styling, {
          primaryColor: "#5C6AC4",
          borderRadius: "8",
          fontSize: "16",
        }),
        branding: parseSafe<WidgetBranding>(config.branding, {
          showPoweredBy: true,
        }),
        customCss: config.customCss,
      },
    });
  } catch (error) {
    if (error instanceof Response) throw error;
    throw json({ error: "Failed to load widget configuration" }, { status: 500 });
  }
};

// ─── Action ───────────────────────────────────────────────────────────────────

export const action = async ({ request }: ActionFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const formData = await request.formData();
  const intent = String(formData.get("intent") ?? "");

  try {
    if (intent !== "save") {
      return json({ error: "Unknown action" }, { status: 400 });
    }

    const position = String(formData.get("position") ?? "embedded");
    const triggerType = String(formData.get("triggerType") ?? "button");

    // Build triggerValue based on type
    const triggerValue: TriggerValue = {};
    if (triggerType === "scroll") {
      const depth = String(formData.get("scrollDepth") ?? "").trim();
      if (depth) triggerValue.scrollDepth = depth;
    } else if (triggerType === "timer") {
      const delay = String(formData.get("delaySeconds") ?? "").trim();
      if (delay) triggerValue.delaySeconds = delay;
    }

    const primaryColor = String(formData.get("primaryColor") ?? "#5C6AC4").trim() || "#5C6AC4";
    const borderRadius = String(formData.get("borderRadius") ?? "8").trim() || "8";
    const fontSize = String(formData.get("fontSize") ?? "16").trim() || "16";
    const showPoweredBy = formData.get("showPoweredBy") === "true";
    const logoUrl = String(formData.get("logoUrl") ?? "").trim() || undefined;
    const customCssRaw = String(formData.get("customCss") ?? "").trim();

    const updates = {
      position,
      triggerType,
      triggerValue: JSON.stringify(triggerValue),
      styling: JSON.stringify({ primaryColor, borderRadius, fontSize }),
      branding: JSON.stringify({ showPoweredBy, ...(logoUrl ? { logoUrl } : {}) }),
      customCss: customCssRaw || null,
      updatedAt: new Date(),
    };

    await db.widgetConfig.upsert({
      where: { shop: session.shop },
      create: { shop: session.shop, ...updates },
      update: updates,
    });

    return json({ success: true, message: "Widget settings saved." });
  } catch (error) {
    if (error instanceof Response) throw error;
    console.error("Widget action failed:", error);
    return json({ error: "Failed to save widget settings." }, { status: 500 });
  }
};

