                    </BlockStack>
                  )}

                  {/* Tab 2 — Branding */}
                  {selectedTab === 2 && (
                    <BlockStack gap="400">
                      <Checkbox
                        label='Show "Powered by QuizSnap" branding'
                        checked={showPoweredBy}
                        onChange={setShowPoweredBy}
                        helpText="Requires Starter plan or higher to disable."
                      />
                      <TextField
                        label="Logo URL (optional)"
