                        onChange={setLogoUrl}
                        autoComplete="off"
                        placeholder="https://cdn.shopify.com/s/files/..."
                        helpText="Display your store logo at the top of the quiz widget."
                      />
                    </BlockStack>
                  )}
                </Box>
              </Tabs>
            </Card>

            {/* Save button at bottom of form */}
            <Box paddingBlockStart="400">
